#define shade r
#define alpha g
#define shadealpha ra

const vec3 gui_orange = pow(vec3(1.0, 0.67058823529411764705882352941176, 0.16470588235294117647058823529412), vec3(2.2));
const vec3 gui_bleed = pow(vec3(1.0, 0.94509803921568627450980392156863, 0.12549019607843137254901960784314), vec3(2.2));

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;

    // bufferA = even frames
    // bufferB = odd frames

    vec2 gui, gui_prev;

    {
        vec2 grey_alpha[2] = vec2[2](textureLod(iChannel0, uv, 0.0f).shadealpha,
                                     textureLod(iChannel1, uv, 0.0f).shadealpha);

		uint cur_frame = uint(iFrame) & 1u;
        uint prev_frame = 1u - cur_frame; 

        gui = grey_alpha[cur_frame];
        gui_prev = grey_alpha[prev_frame];
    }

    float blurDecay = clamp(iTimeDelta * BURNINTIME, 0.0f, 1.0f);
	blurDecay = max(0.0f, blurDecay - gui_prev.shade);

    vec3 color;

    color = mix((gui_bleed - blurDecay), gui_orange * gui.shade, blurDecay);

    fragColor = vec4(pow(color, vec3(1.0f/2.2f)), 1.0f);
}

#define SPEED 6.0
#define BURNINTIME (1.0 / float(iTimeDelta))

// modified font code, originally from https://www.shadertoy.com/view/4dc3zr
// thanks <Flyguy>

const float pi = atan(1.0)*4.0;
const float tau = atan(1.0)*8.0;

const float scale = 1.0 / 12.0;
const float row_spacing = 2.5f * scale;
const uint max_line = 19u;

const vec2 digitSize = vec2(1.0,1.5) * scale;
const vec2 digitSpacing = vec2(1.1,1.6) * scale;

//Distance to a line segment,
float dfLine(vec2 start, vec2 end, vec2 uv)
{
	start *= scale;
	end *= scale;

	vec2 line = end - start;
	float frac = dot(uv - start,line) / dot(line,line);
	return distance(start + line * clamp(frac, 0.0, 1.0), uv);
}

//Distance to the edge of a circle.
float dfCircle(vec2 origin, float radius, vec2 uv)
{
	origin *= scale;
	radius *= scale;

	return abs(length(uv - origin) - radius);
}

//Distance to an arc.
float dfArc(vec2 origin, float start, float sweep, float radius, vec2 uv)
{
	origin *= scale;
	radius *= scale;

	uv -= origin;
	uv *= mat2(cos(start), sin(start),-sin(start), cos(start));

	float offs = (sweep / 2.0 - pi);
	float ang = mod(atan(uv.y, uv.x) - offs, tau) + offs;
	ang = clamp(ang, min(0.0, sweep), max(0.0, sweep));

	return distance(radius * vec2(cos(ang), sin(ang)), uv);
}

float dfDigitBinary(vec2 origin, bool b, vec2 uv)
{
	uv -= origin;

	float dist = 1e6;

	if(!b)
	{
		dist = min(dist, dfLine(vec2(1.000,1.000), vec2(1.000,0.500), uv));
		dist = min(dist, dfLine(vec2(0.000,1.000), vec2(0.000,0.500), uv));
		dist = min(dist, dfArc(vec2(0.500,1.000),0.000, 3.142, 0.500, uv));
		dist = min(dist, dfArc(vec2(0.500,0.500),3.142, 3.142, 0.500, uv));
		return dist;
	}
	/*else*/

    dist = min(dist, dfLine(vec2(0.500,1.500), vec2(0.500,0.000), uv));
    return dist;
}

//Distance to a binary number
float dfBinary(vec2 origin, uint bits, vec2 uv)
{
	uv -= origin;
	float dist = 1e6;
	float offs = float(max_line - 1u);

    for (uint i = 0u ; i < max_line ; ++i) {

    	vec2 pos = digitSpacing * vec2(offs,0.0);  

        --offs;

		dist = min(dist, dfDigitBinary(pos, bool(bits & 1u), uv));

		bits >>= 1;        
    }
	return dist;	
}

// http://bit.ly/supersinfulsilicon

// shader by Jason Tully is licensed under a Creative Commons Attribution-NonCommercial-NoDerivatives 4.0 International License.
// Based on a work at https://www.shadertoy.com/view/WscfRl
// Permissions beyond the scope of this license may be available at http://bit.ly/supersinfulsilicon


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    if (0 != (iFrame & 1))		// only update on even frames, otherwise leave untouched
    {
        fragColor = textureLod(iChannel1, fragCoord.xy / iResolution.xy, 0.0f);
        return;
    }

    vec2 aspect = iResolution.xy / iResolution.y;
	vec2 uv = fragCoord.xy / iResolution.y - aspect/2.0;

    float t = iTime * SPEED;

    uint bits = 0u;

    for (uint i = 0u ; i < max_line ; ++i) {

    	bool b = bool(step(0.5f,textureLod(iChannel0, (vec2(float(i) - t, 0.0f)) / iChannelResolution[0].xy, 0.0).r));

        bits |= uint(b) << i;
    }

    float dist = 1e9;
	vec2 pos = -digitSpacing * vec2(max_line,1.0)/2.0;
    pos.y -= row_spacing;

    uint ut = uint(t);

    { // row
        dist = min(dist, dfBinary(pos, ~ut, uv));
        pos.y += row_spacing;
    }
    { // row
        dist = min(dist, dfBinary(pos, bits, uv));
        pos.y += row_spacing;
    }
    { // row
        dist = min(dist, dfBinary(pos, ut, uv));
        pos.y += row_spacing;
    }
	float shade = 0.0;

	shade = 0.004 / (dist);

    fragColor = vec4(shade);
}

// http://bit.ly/supersinfulsilicon

